iterate.script:
let itemTypeSummaryMap = itemTypeSummaryMapMap[mapKey]
if (!itemTypeSummaryMap) {
    itemTypeSummaryMap = {itemTypeEnumId:invoiceItem.itemTypeEnumId, quantity:toDecimal(0), total:toDecimal(0)}
    if (invoiceItem.itemTypeEnumId === 'ItemTimeEntry') itemTypeSummaryMap.amount = invoiceItem.amount
    itemTypeSummaryMapMap[mapKey] = itemTypeSummaryMap
}
const itemQuantity = toDecimal(invoiceItem.quantity != null ? invoiceItem.quantity : 1)
itemTypeSummaryMap.quantity = itemTypeSummaryMap.quantity.add(itemQuantity)
itemTypeSummaryMap.total = itemTypeSummaryMap.total.add(itemQuantity.multiply(invoiceItem.amount != null ? invoiceItem.amount : 0))

invoiceList.push(invoice)
invoiceTotal = invoiceTotal.add(invoice.invoiceTotal ?? 0)
unpaidTotal = unpaidTotal.add(invoice.unpaidTotal ?? 0)
if (invoice.currencyUomId) currencyUomId = invoice.currencyUomId

// whole days from the date to the as-of moment, then the period index (0 is not yet, 5 is the last)
const agingIndex = (date) => {
    if (date == null) return null
    const days = Math.trunc((Number(asOfTimestamp) - Number(date)) / 86400000)
    return days < 0 ? 0 : Math.min(Math.floor(days / Number(periodDays)) + 1, 5)
}
const invoiceDateIdx = agingIndex(invoice.invoiceDate)
const dueDateIdx = agingIndex(invoice.dueDate)

if (invoiceDateIdx != null) receivableAgingList[invoiceDateIdx] = receivableAgingList[invoiceDateIdx].add(invoice.unpaidTotal ?? 0)
if (dueDateIdx != null) receivableDueAgingList[dueDateIdx] = receivableDueAgingList[dueDateIdx].add(invoice.unpaidTotal ?? 0)

if.script:
// dates are epoch millis in scripts; the due date is computed in the server's zone as Java's systemDefault
const dueDateDt = new Date(Number(invoiceDate))
const termValue = settlementTerm.termValue == null ? null : Math.trunc(toDecimal(settlementTerm.termValue).toNumber())
const setDayOfMonth = () => {
    // the term's day of the month, at most the month's last day
    const maxDays = new Date(dueDateDt.getFullYear(), dueDateDt.getMonth() + 1, 0).getDate()
    dueDateDt.setDate(Math.min(termValue || 1, maxDays))
}
switch (settlementTerm.termTypeEnumId) {
    case 'TtFinPaymentDayNextMonth':
        dueDateDt.setDate(1)
        dueDateDt.setMonth(dueDateDt.getMonth() + 1)
        setDayOfMonth()
        break
    case 'TtFinPaymentDayCurMonth':
        setDayOfMonth()
        break
    default:
        dueDateDt.setDate(dueDateDt.getDate() + (termValue || 0))
}
// could happen for TtFinPaymentDayCurMonth with a day less than today
if (dueDateDt.getTime() < Number(invoiceDate)) {
    dueDateDt.setDate(1)
    dueDateDt.setMonth(dueDateDt.getMonth() + 1)
    setDayOfMonth()
}
const dueDate = dueDateDt.getTime()

if (origDueDate == null || Number(origDueDate) !== dueDate) {
    invoice.dueDate = dueDate
    invoice.update()
}

actions.script:
invoiceItemCreatedCount = 0
amount = toDecimal(0)
const L = (text) => ec.l10n.localize(text)
const billing = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneBilling').parameters({workEffortId: workEffortId}).call() || {}
if (ec.message.hasError()) return
const shares = Array.from(billing.shareList || []).filter((share) => !orderId || (share.orderId === orderId && (!orderItemSeqId || share.orderItemSeqId === orderItemSeqId)))
if (!shares.length) { ec.message.addError(ec.resource.expand('Milestone ${workEffortId} has no billing share', '', {workEffortId})); return }
const due = shares.filter((share) => share.due)
if (!due.length) {
    const first = shares[0]
    ec.message.addError(first.billed ? ec.resource.expand('The share of ${name} is billed on invoice ${invoiceId}', '', {name: first.milestoneName, invoiceId: first.invoiceId})
        : !first.reached ? ec.resource.expand('${name} is not reached yet', '', {name: first.milestoneName})
        : ec.resource.expand('${name} waits for its approval', '', {name: first.milestoneName}))
    return
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const milestone = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    const projectId = milestone.rootWorkEffortId
    const partyOf = (roles) => Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', projectId)
            .condition('roleTypeId', 'in', roles).conditionDate('fromDate', 'thruDate', null).orderBy('fromDate').list())[0]?.partyId || null
    const clientPartyId = partyOf(['Customer', 'CustomerBillTo'])
    const vendorPartyId = partyOf(['Vendor', 'VendorBillFrom'])
    if (!clientPartyId) { ec.message.addError(L('The project has no client')); return }
    if (!vendorPartyId) { ec.message.addError(L('The project has no vendor to bill from')); return }
    const currencies = Array.from(new Set(due.map((share) => share.currencyUomId)))
    if (currencies.length > 1) { ec.message.addError(L('The shares are in more than one currency: invoice each line on its own')); return }
    if (invoiceId) {
        const invoice = ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).forUpdate(true).one()
        if (!invoice || invoice.statusId !== 'InvoiceInProcess' || invoice.toPartyId !== clientPartyId || invoice.fromPartyId !== vendorPartyId) {
            ec.message.addError(ec.resource.expand('Invoice ${invoiceId} is not an open draft from the project\'s vendor to its client', '', {invoiceId})); return }
        if (invoice.currencyUomId && invoice.currencyUomId !== currencies[0]) {
            ec.message.addError(ec.resource.expand('Invoice ${invoiceId} is in ${uom}, the shares in ${shareUom}', '', {invoiceId, uom: invoice.currencyUomId, shareUom: currencies[0]})); return }
    } else {
        invoiceId = ec.service.sync().name('mantle.account.InvoiceServices.create#Invoice').parameters({invoiceTypeEnumId: 'InvoiceSales', fromPartyId: vendorPartyId,
            toPartyId: clientPartyId, invoiceDate: invoiceDate, currencyUomId: currencies[0], settlementTermId: settlementTermId || null,
            description: ec.resource.expand('Invoice for project ${name}', '', {name: (ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', projectId).one()?.workEffortName || projectId)})}).call()?.invoiceId
        if (ec.message.hasError()) return
    }
    const salesTypes = new Set(Array.from(ec.entity.find('moqui.basic.EnumGroupMember').condition('enumGroupEnumId', 'EngItemsSales').useCache(true).list()).map((row) => row.enumId))
    for (const share of due) {
        const item = ec.entity.find('mantle.order.OrderItem').condition({orderId: share.orderId, orderItemSeqId: share.orderItemSeqId}).one()
        const percentText = share.invoicePercent != null ? ec.l10n.format(share.percent, '#,##0.##') + '%' : ec.l10n.formatCurrency(share.amount, share.currencyUomId)
        const description = ec.resource.expand('${milestone}: ${share} of ${line}', '', {milestone: share.milestoneName, share: percentText,
            line: share.itemDescription || (share.orderId + ' ' + share.orderItemSeqId)})
        const seqId = ec.service.sync().name('mantle.account.InvoiceServices.create#InvoiceItem').parameters({invoiceId: invoiceId,
            itemTypeEnumId: item?.itemTypeEnumId && salesTypes.has(item.itemTypeEnumId) ? item.itemTypeEnumId : 'ItemServiceProduct',
            productId: item?.productId || null, quantity: toDecimal(1), amount: share.amount, description: description,
            itemDate: share.reachedDate != null ? share.reachedDate : ec.user.nowTimestamp}).call()?.invoiceItemSeqId
        if (ec.message.hasError()) return
        ec.service.sync().name('create#mantle.work.effort.WorkEffortBilling').parameters({workEffortId: workEffortId, invoiceId: invoiceId, invoiceItemSeqId: seqId,
            percentage: share.percent}).call()
        const lineTotal = toDecimal(share.lineTotal)
        const quantity = lineTotal.isZero() ? toDecimal(0) : toDecimal(item?.quantity ?? 1).multiply(share.amount).divide(lineTotal).setScale(6, 'HALF_UP')
        ec.service.sync().name('create#mantle.order.OrderItemBilling').parameters({orderId: share.orderId, orderItemSeqId: share.orderItemSeqId, invoiceId: invoiceId,
            invoiceItemSeqId: seqId, quantity: quantity, amount: item?.unitAmount ?? share.amount}).call()
        if (ec.message.hasError()) return
        invoiceItemCreatedCount++
        amount = amount.add(share.amount)
    }
    if (!ec.entity.find('mantle.work.effort.WorkEffortInvoice').condition({invoiceId: invoiceId, workEffortId: projectId}).count())
        ec.service.sync().name('create#mantle.work.effort.WorkEffortInvoice').parameters({invoiceId: invoiceId, workEffortId: projectId}).call()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

service-call.in-map:
{invoiceId:invoiceId, workEffortId:workEffortId, timesheetId:timesheetId, thruDate:thruDate,
                        currencyUomId:currencyUomId, ratePurposeEnumId:'RaprVendor', itemTypeEnumId:itemTypeEnumId,
                        workerPartyId:workerPartyId, vendorPartyId:vendorPartyId}

if.script:
if (descendantWorkEffortList?.length) for (const descendant of descendantWorkEffortList) {
    if (!workEffortIdSet.includes(descendant.workEffortId)) workEffortIdSet.push(descendant.workEffortId)
}

actions.script:
entryList = []
itemTotals = {}
hours = toDecimal(0)
amount = toDecimal(0)
projectIdList = []
const clientRows = Array.from(ec.entity.find('mantle.work.time.TimeEntryAndWorkEffort').condition('invoiceId', invoiceId).orderBy('fromDate').orderBy('timeEntryId').list())
workerInvoice = !clientRows.length
const rows = workerInvoice ? Array.from(ec.entity.find('mantle.work.time.TimeEntryAndWorkEffort').condition('vendorInvoiceId', invoiceId)
        .orderBy('fromDate').orderBy('timeEntryId').list()) : clientRows
if (!rows.length) { workerInvoice = false; return }
const names = {}
const nameOf = (id) => {
    if (!id) return ''
    if (!(id in names)) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
        names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
    }
    return names[id]
}
const projects = new Set()
for (const row of rows) {
    const entryHours = toDecimal(row.hours ?? 0)
    const ownRate = workerInvoice ? row.vendorHourRate : row.clientHourRate
    const rateAmountId = workerInvoice ? row.vendorRateAmountId : row.rateAmountId
    const rateAmount = ownRate == null && rateAmountId ? ec.entity.find('mantle.humanres.rate.RateAmount').condition('rateAmountId', rateAmountId).useCache(true).one() : null
    const rate = ownRate != null ? toDecimal(ownRate) : (rateAmount?.rateAmount != null ? toDecimal(rateAmount.rateAmount) : null)
    const entryAmount = rate == null ? null : entryHours.multiply(rate).setScale(2, 'HALF_UP')
    const seqId = (workerInvoice ? row.vendorInvoiceItemSeqId : row.invoiceItemSeqId) || ''
    const project = row.workEffortTypeEnumId === 'WetProject' ? row.workEffortId : (row.rootWorkEffortId || null)
    if (project) projects.add(project)
    entryList.push({timeEntryId: row.timeEntryId, invoiceItemSeqId: seqId || null, partyId: row.partyId, personName: nameOf(row.partyId),
        workEffortId: row.workEffortId || null, workEffortName: row.workEffortName || '', rootWorkEffortId: project,
        fromDate: row.fromDate == null ? null : Number(String(row.fromDate)), thruDate: row.thruDate == null ? null : Number(String(row.thruDate)),
        hours: entryHours, rate: rate, amount: entryAmount, workTypeEnumId: row.workTypeEnumId || null, comments: row.comments || ''})
    const total = itemTotals[seqId] || (itemTotals[seqId] = {hours: toDecimal(0), amount: toDecimal(0), entryCount: 0})
    total.hours = total.hours.add(entryHours)
    if (entryAmount != null) total.amount = total.amount.add(entryAmount)
    total.entryCount++
    hours = hours.add(entryHours)
    if (entryAmount != null) amount = amount.add(entryAmount)
}
projectIdList = Array.from(projects).sort()

service-call.in-map:
{orderId:orderId, orderItemSeqId:orderItem.orderItemSeqId,
                        invoiceId:invoiceId, invoiceItemSeqId:invoiceItemSeqId, quantity:quantityToBill, amount:invoiceItem.amount,
                        shipmentId:curShipmentId, assetReceiptId:curAssetReceiptId, assetIssuanceId:curAssetIssuanceId}

if.script:
ec.service.sync().name("create#mantle.account.invoice.InvoiceEmailMessage")
    .parameter("invoiceId", invoiceId).parameter("emailMessageId", sendOut.emailMessageId).disableAuthz().call()
if (setFinalizedInvoiceSent && invoice.statusId === 'InvoiceFinalized') {
    ec.service.sync().name("update#mantle.account.invoice.Invoice")
        .parameter("invoiceId", invoiceId).parameter("statusId", "InvoiceSent").disableAuthz().call()
    // only try to change status once
    setFinalizedInvoiceSent = false
}
